louca_badge.show:
[[[
  const op = hass.states["sensor.405010538233010720_bsh_common_status_operationstate"]?.state || "";
  const lava = /\.(Run|DelayedStart|Pause)$/.test(op);
  return lava;
]]]

louca_badge.count:
[[[
  const op = hass.states["sensor.405010538233010720_bsh_common_status_operationstate"]?.state || "";
  const lava = /\.(Run|DelayedStart|Pause)$/.test(op);
  const r = hass.states["sensor.405010538233010720_bsh_common_option_remainingprogramtime"];
  if (!lava || !r || ["unavailable", "unknown", ""].includes(r.state)) return null;
  let m = null;
  const v = Number(r.state);
  if (Number.isFinite(v)) m = r.attributes.unit_of_measurement === "min" ? v : v / 60;
  else { const t = Date.parse(r.state); if (!isNaN(t)) m = (t - Date.now()) / 60000; }
  return m != null && m > 0 ? Math.round(m) + "'" : null;
]]]
